const separateParenGroups = (paren_string) => {
  const result = [];
  let current_string = [];
  let current_depth = 0;

  for (const c of paren_string) {
    if (c === '(') {
      current_depth += 1;
      current_string.push(c);
    } else if (c === ')') {
      current_depth -= 1;
      current_string.push(c);

      if (current_depth === 0) {
        result.push(current_string.join(''));
        current_string = [];
      }
    }
  }

  return result;
};
