const separateParenGroups = (paren_string) => {
  const groups = [];
  let current = "";
  let depth = 0;

  for (const char of paren_string) {
    if (char === " ") continue;

    if (char === "(") {
      if (depth === 0) current = "";
      current += char;
      depth++;
    } else if (char === ")") {
      current += char;
      depth--;

      if (depth === 0) {
        groups.push(current);
        current = "";
      }
    }
  }

  return groups;
};
```

