const parseNestedParens = (paren_string) => {
  const parseParenGroup = (s) => {
    let depth = 0;
    let maxDepth = 0;

    for (const c of s) {
      if (c === '(') {
        depth += 1;
        maxDepth = Math.max(maxDepth, depth);
      } else if (c === ')') {
        depth -= 1;
      }
    }

    return maxDepth;
  };

  return paren_string
    .split(' ')
    .filter((x) => x !== '')
    .map((x) => parseParenGroup(x));
};
```

