const findClosestElements = (numbers) => {
  const sorted = [...numbers].sort((a, b) => a - b);

  let closestPair = [sorted[0], sorted[1]];
  let minDistance = Math.abs(sorted[1] - sorted[0]);

  for (let i = 1; i < sorted.length - 1; i++) {
    const distance = Math.abs(sorted[i + 1] - sorted[i]);

    if (distance < minDistance) {
      minDistance = distance;
      closestPair = [sorted[i], sorted[i + 1]];
    }
  }

  return closestPair;
};
