const poly = (xs, x) => {
  let result = 0;
  for (let i = xs.length - 1; i >= 0; i--) {
    result = result * x + xs[i];
  }
  return result;
};

const sign = (x) => (x > 0) - (x < 0);

const findZero = (xs) => {
  let a = -1;
  let b = 1;
  let fa = poly(xs, a);
  let fb = poly(xs, b);

  while (sign(fa) === sign(fb) && fa !== 0 && fb !== 0) {
    a *= 2;
    b *= 2;
    fa = poly(xs, a);
    fb = poly(xs, b);
  }

  for (let i = 0; i < 100; i++) {
    const c = (a + b) / 2;
    const fc = poly(xs, c);
    if (fc === 0) return c;
    if (sign(fa) !== sign(fc)) {
      b = c;
      fb = fc;
    } else {
      a = c;
      fa = fc;
    }
  }

  return (a + b) / 2;
};
