const circularShift = (x, shift) => {
  let str = String(x);
  let sign = '';
  if (str[0] === '-') {
    sign = '-';
    str = str.slice(1);
  }
  const n = str.length;
  if (shift > n) {
    return sign + str.split('').reverse().join('');
  }
  let s = shift % n;
  if (s < 0) s += n;
  if (s === 0) return sign + str;
  return sign + str.slice(n - s) + str.slice(0, n - s);
};
```

