const search = (lst) => {
  const max = Math.max(...lst);
  const frequency = new Array(max + 1).fill(0);

  for (const value of lst) {
    frequency[value] += 1;
  }

  let answer = -1;

  for (let value = 1; value < frequency.length; value++) {
    if (frequency[value] >= value) {
      answer = value;
    }
  }

  return answer;
};
