const decodeShift = (s) => {
  let result = '';
  for (let i = 0; i < s.length; i++) {
    const code = s.charCodeAt(i);
    if (code >= 97 && code <= 122) {
      result += String.fromCharCode(((code - 97 - 5 + 26) % 26) + 97);
    } else {
      result += s[i];
    }
  }
  return result;
};
