const isMultiplyPrime = (a) => {
  if (!Number.isInteger(a) || a < 8) return false;

  let n = a;
  let count = 0;

  for (let p = 2; p * p <= n; p++) {
    while (n % p === 0) {
      count++;
      n /= p;
      if (count > 3) return false;
    }
  }

  if (n > 1) count++;

  return count === 3;
};
```

