  if (n === 1) return x === 1;
  if (n === -1) return x === 1 || x === -1;
  if (n === 0) return x === 0 || x === 1;
  if (x === 1) return true;
  if (x === 0) return n === 0;
  if (x === -1) return false;

  let power = 1;
  while (Math.abs(power) < Math.abs(x)) {
    power *= n;
  }
  return power === x;
};
