const isSimplePower = (x, n) => {
  if (x === 1) return true;
  if (n === 1) return false;
  if (n === 0) return x === 0;
  if (n === -1) return x === 1 || x === -1;
  if (x === 0) return n === 0;

  let power = n;
  if (n > 0) {
    while (power < x) power *= n;
  } else {
    while (Math.abs(power) < Math.abs(x)) power *= n;
  }

  return power === x;
};
