const sortArray = (array) => {
  const arr = array.slice();

  if (arr.length <= 1) {
    return arr;
  }

  const sum = arr[0] + arr[arr.length - 1];
  const ascending = sum % 2 === 1;

  arr.sort((a, b) => (ascending ? a - b : b - a));

  return arr;
};
