const evenOddPalindrome = (n) => {
  let even = 0;
  let odd = 0;

  for (let i = 1; i <= n; i++) {
    const s = String(i);
    let isPalindrome = true;

    for (let left = 0, right = s.length - 1; left < right; left++, right--) {
      if (s[left] !== s[right]) {
        isPalindrome = false;
        break;
      }
    }

    if (isPalindrome) {
      if (i % 2 === 0) {
        even++;
      } else {
        odd++;
      }
    }
  }

  return [even, odd];
};
