const countNums = (arr) => {
  let count = 0;

  for (let i = 0; i < arr.length; i++) {
    let num = arr[i];

    if (num > 0) {
      count++;
      continue;
    }

    let sum = 0;
    num = -num;

    while (num >= 10) {
      sum += num % 10;
      num = (num - (num % 10)) / 10;
    }

    sum -= num;

    if (sum > 0) {
      count++;
    }
  }

  return count;
};
