const sortArray = (arr) => {
  const countOnes = (n) => {
    let count = 0;
    const binary = n.toString(2);
    for (let i = 0; i < binary.length; i++) {
      if (binary[i] === '1') count++;
    }
    return count;
  };

  return arr.slice().sort((a, b) => {
    const onesA = countOnes(a);
    const onesB = countOnes(b);
    if (onesA !== onesB) return onesA - onesB;
    return a - b;
  });
};
