const getOddCollatz = (n) => {
  const odds = [];
  let current = n;

  while (true) {
    if (current % 2 === 1) {
      odds.push(current);
    }

    if (current === 1) {
      break;
    }

    current = current % 2 === 0 ? current / 2 : 3 * current + 1;
  }

  return odds.sort((a, b) => a - b);
};
