const isNested = (string) => {
  let openCount = 0;
  let secondOpenIndex = -1;
  for (let i = 0; i < string.length; i++) {
    if (string[i] === '[') {
      openCount++;
      if (openCount === 2) {
        secondOpenIndex = i;
        break;
      }
    }
  }
  if (secondOpenIndex === -1) return false;

  let closeCount = 0;
  let secondLastCloseIndex = -1;
  for (let i = string.length - 1; i >= 0; i--) {
    if (string[i] === ']') {
      closeCount++;
      if (closeCount === 2) {
        secondLastCloseIndex = i;
        break;
      }
    }
  }
  if (secondLastCloseIndex === -1) return false;

  return secondOpenIndex < secondLastCloseIndex;
};
