  const afterDot = file_name.slice(dotIndex + 1);

  if (beforeDot.length === 0) return 'No';
  if (!/^[A-Za-z]/.test(beforeDot)) return 'No';
  if (!['txt', 'exe', 'dll'].includes(afterDot)) return 'No';

  return 'Yes';
};

