const digitSum = (n) => {
  let sign = 1;
  let value = n;

  if (value < 0) {
    sign = -1;
    value = -value;
  }

  let sum = 0;

  while (value >= 10) {
    sum += value % 10;
    value = (value - (value % 10)) / 10;
  }

  sum += sign * value;
  return sum;
};

const orderByPoints = (nums) => {
  const indexed = nums.map((value, index) => ({
    value,
    index,
    points: digitSum(value),
  }));

  indexed.sort((a, b) => a.points - b.points || a.index - b.index);

  for (let i = 0; i < nums.length; i++) {
    nums[i] = indexed[i].value;
  }

  return nums;
};
```

