const getPoints = (num) => {
  if (num === 0) return 0;
  const isNegative = num < 0;
  const str = Math.abs(num).toString();
  const leading = parseInt(str[0], 10);
  let sum = 0;
  for (let i = 0; i < str.length; i++) {
    sum += parseInt(str[i], 10);
  }
  return isNegative ? sum - leading : sum + leading;
};

const orderByPoints = (nums) => {
  return nums
    .map((value, index) => ({ value, index, points: getPoints(value) }))
    .sort((a, b) => a.points - b.points || a.index - b.index)
    .map(item => item.value);
};
