const doAlgebra = (operator, operand) => {
  const ops = operator.slice();
  const nums = operand.slice();

  while (ops.length > 0) {
    let applied = false;

    // Exponentiation: right-associative, highest precedence
    for (let i = ops.length - 1; i >= 0; i--) {
      if (ops[i] === '**') {
        nums[i] = nums[i] ** nums[i + 1];
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        applied = true;
        break;
      }
    }
    if (applied) continue;

    // Multiplication and floor division: left-associative
    for (let i = 0; i < ops.length; i++) {
      if (ops[i] === '*') {
        nums[i] = nums[i] * nums[i + 1];
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        applied = true;
        break;
      }
      if (ops[i] === '//') {
        nums[i] = Math.floor(nums[i] / nums[i + 1]);
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        applied = true;
        break;
      }
    }
    if (applied) continue;

    // Addition and subtraction: left-associative
    for (let i = 0; i < ops.length; i++) {
      if (ops[i] === '+') {
        nums[i] = nums[i] + nums[i + 1];
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        applied = true;
        break;
      }
      if (ops[i] === '-') {
        nums[i] = nums[i] - nums[i + 1];
        nums.splice(i + 1, 1);
        ops.splice(i, 1);
        applied = true;
        break;
      }
    }
  }

  return nums[0];
};
