const doAlgebra = (operator, operand) => {
  const precedence = { '+': 1, '-': 1, '*': 2, '//': 2, '**': 3 };
  const associativity = { '+': 'left', '-': 'left', '*': 'left', '//': 'left', '**': 'right' };

  const tokens = [];
  for (let i = 0; i < operand.length; i++) {
    tokens.push(operand[i]);
    if (i < operator.length) tokens.push(operator[i]);
  }

  const output = [];
  const ops = [];

  for (const token of tokens) {
    if (typeof token === 'number') {
      output.push(token);
    } else {
      while (ops.length) {
        const top = ops[ops.length - 1];
        const pTop = precedence[top];
        const pToken = precedence[token];

        if (pTop > pToken || (pTop === pToken && associativity[token] === 'left')) {
          output.push(ops.pop());
        } else {
          break;
        }
      }
      ops.push(token);
    }
  }

  while (ops.length) output.push(ops.pop());

  const stack = [];
  for (const token of output) {
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      const b = stack.pop();
      const a = stack.pop();
      let result;

      switch (token) {
        case '+':
          result = a + b;
          break;
        case '-':
          result = a - b;
          break;
        case '*':
          result = a * b;
