const orderByPoints = (nums) => {
  const digitSum = (n) => {
    let sum = n < 0 ? -1 : 0;
    n = Math.abs(n);
    while (n > 0) {
      sum += n % 10;
      n = Math.floor(n / 10);
    }
    return sum;
  };

  return nums
    .map((num, index) => ({ num, index, points: digitSum(num) }))
    .sort((a, b) => a.points - b.points || b.index - a.index)
    .map(({ num }) => num);
};
