const separateParenGroups = (paren_string) => {
  const result = [];
  let current = '';
  let depth = 0;

  for (const char of paren_string) {
    if (char === ' ') continue;

    if (char === '(') {
      depth++;
      current += char;
    } else if (char === ')') {
      current += char;
      depth--;

      if (depth === 0) {
        result.push(current);
        current = '';
      }
    }
  }

  return result;
};
