const findZero = (xs) => {
  let n = xs.length;
  while (n > 1 && xs[n - 1] === 0) n--;
  const a = xs.slice(0, n);
  const lead = a[n - 1];

  let max = 0;
  for (let i = 0; i < n - 1; i++) {
    max = Math.max(max, Math.abs(a[i] / lead));
  }

  let lo = -(1 + max);
  let hi = 1 + max;

  const f = (x) => {
    let res = a[n - 1];
    for (let i = n - 2; i >= 0; i--) {
      res = res * x + a[i];
    }
    return res;
  };

  let flo = f(lo);
  let fhi = f(hi);

  if (flo === 0) return lo;
  if (fhi === 0) return hi;

  for (let i = 0; i < 200; i++) {
    const mid = (lo + hi) / 2;
    const fmid = f(mid);

    if (fmid === 0) return mid;

    if (Math.sign(fmid) === Math.sign(flo)) {
      lo = mid;
      flo = fmid;
    } else {
      hi = mid;
      fhi = fmid;
    }
  }

  return (lo + hi) / 2;
};
