const fizzBuzz = (n) => {
  if (n <= 0) return 0;

  const countSevens = (limit, divisor) => {
    if (limit < 0) return 0;

    const digits = String(limit).split('').map(Number);
    const memo = new Map();

    const dp = (pos, mod, tight) => {
      if (pos === digits.length) {
        return { count: mod === 0 ? 1 : 0, total: 0 };
      }

      const key = `${pos},${mod},${tight}`;
      if (!tight && memo.has(key)) return memo.get(key);

      const max = tight ? digits[pos] : 9;
      let count = 0;
      let total = 0;

      for (let digit = 0; digit <= max; digit++) {
        const nextTight = tight && digit === max;
        const nextMod = (mod * 10 + digit) % divisor;
        const sub = dp(pos + 1, nextMod, nextTight);

        count += sub.count;
        total += sub.total + (digit === 7 ? sub.count : 0);
      }

      const result = { count, total };
      if (!tight) memo.set(key, result);
      return result;
    };

    return dp(0, 0, true).total;
  };

  const limit = n - 1;
  return countSevens(limit, 11) + countSevens(limit, 13) - countSevens(limit, 143);
};
