const findZero = (xs) => {
  const n = xs.length - 1;
  const leading = xs[n];

  const poly = (x) => {
    let res = 0;
    for (let i = n; i >= 0; i--) {
      res = res * x + xs[i];
    }
    return res;
  };

  if (poly(0) === 0) return 0;

  let a = -1;
  let b = 1;
  let fa = poly(a);
  let fb = poly(b);

  if (fa === 0) return a;
  if (fb === 0) return b;

  if (leading > 0) {
    while (fa > 0) {
      a *= 2;
      fa = poly(a);
      if (fa === 0) return a;
    }
    while (fb < 0) {
      b *= 2;
      fb = poly(b);
      if (fb === 0) return b;
    }
  } else {
    while (fa < 0) {
      a *= 2;
      fa = poly(a);
      if (fa === 0) return a;
    }
    while (fb > 0) {
      b *= 2;
      fb = poly(b);
      if (fb === 0) return b;
    }
  }

  for (let i = 0; i < 100; i++) {
    const m = (a + b) / 2;
    const fm = poly(m);
    if (fm === 0) return m;
    if ((fa < 0 && fm < 0) || (fa > 0 && fm > 0)) {
      a = m;
      fa = fm;
    } else {
      b = m;
      fb = fm;
    }
  }

  return (a + b) / 2;
};
