const fizzBuzz = (n) => {
  if (n <= 0) return 0;
  const N = n - 1;

  const countFor = (d) => {
    const digits = String(N).split('').map(Number);
    const L = digits.length;
    const memo = new Map();

    const dp = (pos, mod, tight) => {
      if (pos === L) {
        return mod === 0 ? [1, 0] : [0, 0];
      }

      const key = `${pos},${mod},${tight}`;
      if (memo.has(key)) return memo.get(key);

      const limit = tight ? digits[pos] : 9;
      let count = 0;
      let sum = 0;

      for (let digit = 0; digit <= limit; digit++) {
        const nextMod = (mod * 10 + digit) % d;
        const nextTight = tight && digit === limit;
        const [subCount, subSum] = dp(pos + 1, nextMod, nextTight);

        count += subCount;
        sum += subSum + (digit === 7 ? subCount : 0);
      }

      const result = [count, sum];
      memo.set(key, result);
      return result;
    };

    return dp(0, 0, true)[1];
  };

  return countFor(11) + countFor(13) - countFor(143);
};
