  if (mod === 1n) return 0;

  let result = 1n;
  let base = 2n % mod;
  let exp = BigInt(n);

  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % mod;
    base = (base * base) % mod;
    exp >>= 1n;
  }

  return Number(result);
};
