const modp = (n, p) => {
  const P = BigInt(p);
  if (P === 1n) return typeof p === 'bigint' ? 0n : 0;
  let base = 2n % P;
  let exp = BigInt(n);
  let result = 1n;
  while (exp > 0n) {
    if (exp & 1n) result = (result * base) % P;
    base = (base * base) % P;
    exp >>= 1n;
  }
  return typeof p === 'bigint' ? result : Number(result);
};

