const largestPrimeFactor = (n) => {
  let max = 1;
  let num = n;

  while (num % 2 === 0) {
    max = 2;
    num /= 2;
  }

  for (let factor = 3; factor * factor <= num; factor += 2) {
    while (num % factor === 0) {
      max = factor;
      num /= factor;
    }
  }

  if (num > 1) {
    max = num;
  }

  return max;
};
