const circularShift = (x, shift) => {
  const sign = x < 0 ? "-" : "";
  const digits = Math.abs(x).toString();
  const n = digits.length;

  if (shift > n) {
    return sign + digits.split("").reverse().join("");
  }

  const k = shift % n;

  if (k === 0) {
    return sign + digits;
  }

  return sign + digits.slice(-k) + digits.slice(0, -k);
};
```

