const circularShift = (x, shift) => {
  const digits = Math.abs(x).toString();
  const n = digits.length;

  if (shift > n) {
    return digits.split('').reverse().join('');
  }

  let k = shift % n;
  if (k < 0) k += n;
  if (k === 0) return digits;

  return digits.slice(n - k) + digits.slice(0, n - k);
};
```

