const isMultiplyPrime = (a) => {
  if (a < 2) return false;

  let n = a;
  let count = 0;

  for (let p = 2; p * p <= n; p++) {
    while (n % p === 0) {
      n /= p;
      count++;
      if (count > 3) return false;
    }
  }

  if (n > 1) count++;

  return count === 3;
};
```

