const isSimplePower = (x, n) => {
  if (x === 1) return true;
  if (x === 0) return n === 0;
  if (n === 1) return false;
  if (n === 0) return false;
  if (n === -1) return x === -1;

  let power = 1;
  while (Math.abs(power) <= Math.abs(x)) {
    power *= n;
    if (power === x) return true;
    if (Math.abs(power) > Math.abs(x)) break;
  }
  return false;
};
```

