const isLowerCaseKey = (key) => {
  let hasCased = false;
  for (const ch of key) {
    const lower = ch.toLowerCase();
    const upper = ch.toUpperCase();
    if (lower !== upper) {
      hasCased = true;
      if (ch !== lower) return false;
    }
  }
  return hasCased;
};

const isUpperCaseKey = (key) => {
  let hasCased = false;
  for (const ch of key) {
    const lower = ch.toLowerCase();
    const upper = ch.toUpperCase();
    if (lower !== upper) {
      hasCased = true;
      if (ch !== upper) return false;
    }
  }
  return hasCased;
};

const checkDictCase = (dict) => {
  if (dict == null || typeof dict !== 'object') return false;

  const keys = Object.keys(dict);
  if (keys.length === 0) return false;

  let allLower = true;
  let allUpper = true;

  for (const key of keys) {
    if (!isLowerCaseKey(key)) allLower = false;
    if (!isUpperCaseKey(key)) allUpper = false;
    if (!allLower && !allUpper) return false;
  }

  return allLower || allUpper;
};
