  let even = 0;
  let odd = 0;

  const isPalindrome = (num) => {
    const str = String(num);
    let left = 0;
    let right = str.length - 1;

    while (left < right) {
      if (str[left] !== str[right]) return false;
      left++;
      right--;
    }

    return true;
  };

  for (let i = 1; i <= n; i++) {
    if (isPalindrome(i)) {
      if (i % 2 === 0) {
        even++;
      } else {
        odd++;
      }
    }
  }

  return [even, odd];
};
