const countNums = (arr) => {
  let count = 0;

  for (const num of arr) {
    const str = String(num);
    let sum = 0;
    let isNegative = false;
    let isFirstDigit = true;

    for (let i = 0; i < str.length; i++) {
      const ch = str[i];

      if (ch === '-') {
        isNegative = true;
        continue;
      }

      const digit = ch.charCodeAt(0) - 48;

      if (isNegative && isFirstDigit) {
        sum -= digit;
      } else {
        sum += digit;
      }

      isFirstDigit = false;
    }

    if (sum > 0) {
      count++;
    }
  }

  return count;
};
