const countNums = (arr) => {
  const signedDigitSum = (num) => {
    const isNegative = num < 0;
    const digits = Math.abs(num).toString();
    let sum = 0;

    for (let i = 0; i < digits.length; i++) {
      let digit = Number(digits[i]);
      if (isNegative && i === 0) {
        digit = -digit;
      }
      sum += digit;
    }

    return sum;
  };

  return arr.filter((num) => signedDigitSum(num) > 0).length;
};
