const matchParens = (lst) => {
  const isGood = (s) => {
    let balance = 0;
    for (const ch of s) {
      if (ch === '(') {
        balance++;
      } else {
        balance--;
      }
      if (balance < 0) return false;
    }
    return balance === 0;
  };

  const [a, b] = lst;
  return isGood(a + b) || isGood(b + a) ? 'Yes' : 'No';
};
