const splitWords = (txt) => {
  if (/\s/.test(txt)) {
    return txt.trim().split(/\s+/).filter(Boolean);
  }
  if (txt.includes(',')) {
    return txt.split(',');
  }
  let count = 0;
  for (let i = 0; i < txt.length; i++) {
    const code = txt.charCodeAt(i);
    if (code >= 97 && code <= 122) {
      const order = code - 97;
      if (order % 2 === 1) count++;
    }
  }
  return count;
};
