const minPath = (grid, k) => {
  const n = grid.length;
  let r = 0;
  let c = 0;

  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) {
        r = i;
        c = j;
      }
    }
  }

  const result = [1];
  const directions = [
    [-1, 0],
    [1, 0],
    [0, -1],
    [0, 1],
  ];

  for (let step = 1; step < k; step++) {
    let bestValue = Infinity;
    let bestR = r;
    let bestC = c;

    for (const [dr, dc] of directions) {
      const nr = r + dr;
      const nc = c + dc;

      if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
        const value = grid[nr][nc];
        if (value < bestValue) {
          bestValue = value;
          bestR = nr;
          bestC = nc;
        }
      }
    }

    r = bestR;
    c = bestC;
    result.push(bestValue);
  }

  return result;
};
