const minPath = (grid, k) => {
  const n = grid.length;
  let r, c;

  // Find the cell containing 1
  for (let i = 0; i < n; i++) {
    for (let j = 0; j < n; j++) {
      if (grid[i][j] === 1) {
        r = i;
        c = j;
        break;
      }
    }
    if (r !== undefined) break;
  }

  // Find the smallest neighbor of 1
  const dirs = [[-1, 0], [1, 0], [0, -1], [0, 1]];
  let minNeighbor = Infinity;
  for (const [dr, dc] of dirs) {
    const nr = r + dr;
    const nc = c + dc;
    if (nr >= 0 && nr < n && nc >= 0 && nc < n) {
      if (grid[nr][nc] < minNeighbor) {
        minNeighbor = grid[nr][nc];
      }
    }
  }

  // The optimal path alternates between 1 and its smallest neighbor
  const result = [];
  for (let i = 0; i < k; i++) {
    result.push(i % 2 === 0 ? 1 : minNeighbor);
  }

  return result;
};
