const isNested = (string) => {
  let firstOpen = -1;
  let secondOpen = -1;
  for (let i = 0; i < string.length; i++) {
    if (string[i] === '[') {
      if (firstOpen === -1) {
        firstOpen = i;
      } else {
        secondOpen = i;
        break;
      }
    }
  }
  if (secondOpen === -1) return false;

  let lastClose = -1;
  let secondLastClose = -1;
  for (let i = string.length - 1; i >= 0; i--) {
    if (string[i] === ']') {
      if (lastClose === -1) {
        lastClose = i;
      } else {
        secondLastClose = i;
        break;
      }
    }
  }
  if (secondLastClose === -1) return false;

  return secondOpen < secondLastClose;
};
