const orderByPoints = (nums) => {
  const getPoints = (n) => {
    const absStr = Math.abs(n).toString();
    let sum = 0;
    for (let i = 0; i < absStr.length; i++) {
      sum += Number(absStr[i]);
    }
    if (n < 0) {
      sum -= absStr.length;
    }
    return sum;
  };

  return nums
    .map((num, index) => ({ num, index, points: getPoints(num) }))
    .sort((a, b) => a.points - b.points || a.index - b.index)
    .map((item) => item.num);
};
