const findMax = (words) => {
  if (!Array.isArray(words) || words.length === 0) return null;

  let best = null;
  let maxUnique = -1;

  for (const word of words) {
    const uniqueCount = new Set(word).size;

    if (
      uniqueCount > maxUnique ||
      (uniqueCount === maxUnique && (best === null || word < best))
    ) {
      maxUnique = uniqueCount;
      best = word;
    }
  }

  return best;
};
