const doAlgebra = (operator, operand) => {
  const precedence = {
    '+': 1,
    '-': 1,
    '*': 2,
    '//': 2,
    '**': 3
  };

  const isLeftAssoc = (op) => op !== '**';

  const applyOp = (op, b, a) => {
    switch (op) {
      case '+': return a + b;
      case '-': return a - b;
      case '*': return a * b;
      case '//': return Math.floor(a / b);
      case '**': return a ** b;
    }
  };

  const values = [];
  const ops = [];

  const tokens = [];
  for (let i = 0; i < operand.length; i++) {
    tokens.push(operand[i]);
    if (i < operator.length) {
      tokens.push(operator[i]);
    }
  }

  for (const token of tokens) {
    if (typeof token === 'number') {
      values.push(token);
    } else {
      const op = token;
      while (
        ops.length > 0 &&
        (precedence[ops[ops.length - 1]] > precedence[op] ||
          (precedence[ops[ops.length - 1]] === precedence[op] && isLeftAssoc(op)))
      ) {
        const topOp = ops.pop();
        const b = values.pop();
        const a = values.pop();
        values.push(applyOp(topOp, b, a));
      }
      ops.push(op);
    }
  }

  while (ops.length > 0) {
    const topOp = ops.pop();
    const b = values.pop();
    const a = values.pop();
    values.push(applyOp(topOp, b, a));
  }

  return values[0];
};
