const solve = (s) => {
  if (!/[a-zA-Z]/.test(s)) {
    return s.split('').reverse().join('');
  }

  return s.replace(/[a-zA-Z]/g, (char) => {
    return char === char.toLowerCase()
      ? char.toUpperCase()
      : char.toLowerCase();
  });
};
