const doAlgebra = (operator, operand) => {
  const precedence = {
    '+': 1,
    '-': 1,
    '*': 2,
    '//': 2,
    '**': 3
  };

  const rightAssociative = {
    '**': true
  };

  const tokens = [];
  for (let i = 0; i < operand.length; i++) {
    tokens.push(operand[i]);
    if (i < operator.length) {
      tokens.push(operator[i]);
    }
  }

  const output = [];
  const ops = [];

  for (const token of tokens) {
    if (typeof token === 'number') {
      output.push(token);
    } else {
      const op = token;
      while (ops.length > 0) {
        const top = ops[ops.length - 1];
        const topPrec = precedence[top];
        const opPrec = precedence[op];

        if (
          topPrec > opPrec ||
          (topPrec === opPrec && !rightAssociative[op])
        ) {
          output.push(ops.pop());
        } else {
          break;
        }
      }
      ops.push(op);
    }
  }

  while (ops.length > 0) {
    output.push(ops.pop());
  }

  const stack = [];

  for (const token of output) {
    if (typeof token === 'number') {
      stack.push(token);
    } else {
      const b = stack.pop();
      const a = stack.pop();
      let result;

      switch (token) {
        case '+':
          result = a + b;
          break;
        case '-':
          result = a - b;
          break;
        case '*':
          result = a * b;
          break;
        case '//':
          result = Math.floor(a / b);
          break;
        case '**':
          result = a ** b;
          break;
      }

      stack.push(result);
    }
  }

  return stack[0];
};
